//! Cross-ISA semantic translation map.
//!
//! Source and target instructions are compared after lowering to the typed
//! semantic IR and alpha-normalizing operand symbols by role and position.
//! This makes `add x0, x1, x2` match a custom accelerator add even when the
//! two descriptions use different operand names.

use super::common::*;

pub fn emit_translation_python(document: &Document) -> String {
    let manifest = emit_translation_map_json(document);
    format!(
        "# Generated by AXIS. Standalone explicit-lowering matcher/rewriter.\n\
AXIS_SCHEMA = \"axis.translation-python.v1\"\n\
import json\n\n\
TRANSLATION_MAP = json.loads({})\n\
RULES = sorted(\n\
    TRANSLATION_MAP[\"explicit_lowerings\"],\n\
    key=lambda rule: (-len(rule[\"source_sequence\"]), -float(rule[\"cost\"][\"benefit\"]), rule[\"name\"]),\n\
)\n\n\
{}",
        json_string(&manifest),
        TRANSLATION_PY_RUNTIME
    )
}

pub fn emit_translation_map_json(document: &Document) -> String {
    let sources: Vec<&Instruction> = document
        .instructions
        .iter()
        .filter(|instruction| instruction_role(document, instruction) == Some("source"))
        .collect();
    let targets: Vec<&Instruction> = document
        .instructions
        .iter()
        .filter(|instruction| instruction_role(document, instruction) == Some("target"))
        .collect();

    let mut matches = Vec::new();
    let mut matched_sources = std::collections::HashSet::new();
    for source in &sources {
        let Some(source_key) = translation_key(document, source) else {
            continue;
        };
        for target in &targets {
            let Some(target_key) = translation_key(document, target) else {
                continue;
            };
            if source_key == target_key {
                matched_sources.insert(source.mnemonic.as_str());
                matches.push(translation_match_json(
                    document,
                    source,
                    target,
                    &source_key,
                ));
            }
        }
    }

    let unmatched: Vec<String> = sources
        .iter()
        .filter(|source| !matched_sources.contains(source.mnemonic.as_str()))
        .map(|source| source.mnemonic.clone())
        .collect();

    let mut out = String::new();
    out.push_str("{\n");
    line(&mut out, 1, "\"schema\": \"axis.translation-map.v1\",");
    line(
        &mut out,
        1,
        &format!("\"name\": {},", json_string(&document.extension.name)),
    );
    line(
        &mut out,
        1,
        &format!("\"source_instruction_count\": {},", sources.len()),
    );
    line(
        &mut out,
        1,
        &format!("\"target_instruction_count\": {},", targets.len()),
    );
    line(
        &mut out,
        1,
        &format!("\"explicit_lowering_count\": {},", document.lowerings.len()),
    );
    line(&mut out, 1, "\"matches\": [");
    for (idx, item) in matches.iter().enumerate() {
        let suffix = if idx + 1 == matches.len() { "" } else { "," };
        line(&mut out, 2, &format!("{item}{suffix}"));
    }
    line(&mut out, 1, "],");
    line(&mut out, 1, "\"explicit_lowerings\": [");
    for (idx, lowering) in document.lowerings.iter().enumerate() {
        let suffix = if idx + 1 == document.lowerings.len() {
            ""
        } else {
            ","
        };
        line(
            &mut out,
            2,
            &format!("{}{suffix}", explicit_lowering_json(document, lowering)),
        );
    }
    line(&mut out, 1, "],");
    line(
        &mut out,
        1,
        &format!("\"unmatched_sources\": {}", json_list(&unmatched)),
    );
    out.push_str("}\n");
    out
}

const TRANSLATION_PY_RUNTIME: &str = r#"def _extract(word, fields):
    value = 0
    for field in fields:
        mask = (1 << field["width"]) - 1
        value |= ((word >> field["insn_lo"]) & mask) << field["op_lo"]
    return value


def _operand(step, word, name):
    for binding in step["bindings"]:
        if binding["operand"] == name:
            return _extract(word, binding["fields"])
    return None


def _instruction_constraint_ok(step, word, constraint=None):
    constraint = step.get("decode_constraint") if constraint is None else constraint
    if constraint is None:
        return True
    kind = constraint["kind"]
    if kind == "a64_logical_imm":
        n_spec = constraint["n"]
        n = n_spec["value"] if n_spec["kind"] == "literal" else _operand(
            step, word, n_spec["name"]
        )
        imms = _operand(step, word, constraint["imms"])
        if n is None or imms is None or (constraint["width"] == 32 and n != 0):
            return False
        encoded = ((n & 1) << 6) | ((~imms) & 0x3f)
        length = encoded.bit_length() - 1
        if length < 1:
            return False
        levels = (1 << length) - 1
        return (imms & levels) != levels
    if kind == "a64_shifted_reg":
        shift = _operand(step, word, constraint["shift"])
        amount = _operand(step, word, constraint["amount"])
        return shift is not None and amount is not None and shift < 3 and amount < constraint["width"]
    if kind == "a64_extended_reg":
        amount = _operand(step, word, constraint["amount"])
        return amount is not None and amount < 5
    if kind == "uimm_compare":
        value = _operand(step, word, constraint["operand"])
        if value is None:
            return False
        literal = constraint["literal"]
        return {
            "eq": value == literal,
            "ne": value != literal,
            "lt": value < literal,
            "le": value <= literal,
            "gt": value > literal,
            "ge": value >= literal,
        }.get(constraint["op"], False)
    if kind == "uimm_mask_eq":
        value = _operand(step, word, constraint["operand"])
        return value is not None and (value & constraint["mask"]) == constraint["value"]
    if kind == "and":
        return all(_instruction_constraint_ok(step, word, child)
                   for child in constraint["constraints"])
    if kind == "or":
        return any(_instruction_constraint_ok(step, word, child)
                   for child in constraint["constraints"])
    if kind == "not":
        return not _instruction_constraint_ok(step, word, constraint["constraint"])
    return False


def _bind_step(step, word, values):
    match = int(step["match"], 16)
    mask = int(step["mask"], 16)
    if (word & mask) != match or not _instruction_constraint_ok(step, word):
        return None
    bound = dict(values)
    for binding in step["bindings"]:
        operand_value = _extract(word, binding["fields"])
        spec = binding["value"]
        if spec["kind"] == "literal":
            if operand_value != spec["value"]:
                return None
            continue
        name = spec["name"]
        if name in bound and bound[name] != operand_value:
            return None
        bound[name] = operand_value
    return bound


def _lowering_value(spec, values):
    return spec["value"] if spec["kind"] == "literal" else values[spec["name"]]


def _predicate_ok(predicate, values):
    if predicate is None:
        return True
    kind = predicate["kind"]
    if kind == "and":
        return all(_predicate_ok(child, values) for child in predicate["predicates"])
    if kind == "or":
        return any(_predicate_ok(child, values) for child in predicate["predicates"])
    if kind == "not":
        return not _predicate_ok(predicate["predicate"], values)
    lhs = _lowering_value(predicate["lhs"], values)
    rhs = _lowering_value(predicate["rhs"], values)
    return {
        "eq": lhs == rhs,
        "ne": lhs != rhs,
        "lt": lhs < rhs,
        "le": lhs <= rhs,
        "gt": lhs > rhs,
        "ge": lhs >= rhs,
    }.get(predicate["op"], False)


def _encode_target(step, values):
    word = int(step["match"], 16)
    for binding in step["bindings"]:
        value = _lowering_value(binding["value"], values)
        for field in binding["fields"]:
            mask = (1 << field["width"]) - 1
            word &= ~(mask << field["insn_lo"])
            word |= ((value >> field["op_lo"]) & mask) << field["insn_lo"]
        if _extract(word, binding["fields"]) != value:
            return None
    if not _instruction_constraint_ok(step, word):
        return None
    return word


def match_at(words, index=0, source_isa=None, target_isa=None):
    """Return the best explicit lowering match at `index`, or None."""
    for rule in RULES:
        sequence = rule["source_sequence"]
        if index + len(sequence) > len(words):
            continue
        if source_isa is not None and any(step["isa"] != source_isa for step in sequence):
            continue
        if target_isa is not None and rule["target"]["isa"] != target_isa:
            continue
        values = {}
        for offset, step in enumerate(sequence):
            values = _bind_step(step, words[index + offset], values)
            if values is None:
                break
        if values is None or not _predicate_ok(rule["requires"], values):
            continue
        target_word = _encode_target(rule["target"], values)
        if target_word is None:
            continue
        return {
            "rule": rule["name"],
            "index": index,
            "consumed": len(sequence),
            "target_isa": rule["target"]["isa"],
            "target_mnemonic": rule["target"]["mnemonic"],
            "target_word": target_word,
            "bindings": values,
            "cost": rule["cost"],
        }
    return None


def rewrite_once(words, index=0, source_isa=None, target_isa=None):
    """Apply at most one lowering and return `(new_words, match)`."""
    match = match_at(words, index, source_isa, target_isa)
    if match is None:
        return list(words), None
    rewritten = (
        list(words[:index])
        + [match["target_word"]]
        + list(words[index + match["consumed"]:])
    )
    return rewritten, match


def rewrite_all(words, source_isa=None, target_isa=None):
    """Greedily rewrite a word stream, preferring longer and higher-benefit rules."""
    output = []
    applied = []
    index = 0
    while index < len(words):
        match = match_at(words, index, source_isa, target_isa)
        if match is None:
            output.append(words[index])
            index += 1
            continue
        output.append(match["target_word"])
        applied.append(match)
        index += match["consumed"]
    return output, applied
"#;

fn explicit_lowering_json(document: &Document, lowering: &Lowering) -> String {
    let sources = lowering
        .sources
        .iter()
        .map(|step| lowering_step_json(document, step))
        .collect::<Vec<_>>()
        .join(", ");
    let requires = lowering
        .requires
        .as_ref()
        .map(lowering_predicate_json)
        .unwrap_or_else(|| "null".to_string());
    let preserved_state = lowering
        .sources
        .iter()
        .filter_map(|step| {
            document.instructions.iter().find(|instruction| {
                instruction.mnemonic.eq_ignore_ascii_case(&step.instruction)
                    || instruction.name.eq_ignore_ascii_case(&step.instruction)
            })
        })
        .filter_map(|instruction| instruction.behavior.as_ref())
        .flat_map(|behavior| &behavior.effects)
        .filter_map(|effect| match &effect.loc {
            crate::effects::Loc::State { name, width } => Some(format!("{name}:i{width}")),
            _ => None,
        })
        .collect::<std::collections::BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let memory_effects = lowering
        .sources
        .iter()
        .filter_map(|step| {
            document.instructions.iter().find(|instruction| {
                instruction.mnemonic.eq_ignore_ascii_case(&step.instruction)
                    || instruction.name.eq_ignore_ascii_case(&step.instruction)
            })
        })
        .filter_map(|instruction| instruction.behavior.as_ref())
        .flat_map(|behavior| &behavior.effects)
        .filter_map(|effect| match &effect.loc {
            crate::effects::Loc::Mem {
                width,
                order,
                atomic,
                ..
            } => {
                let operation = if *atomic { "atomic-store" } else { "store" };
                Some(if *order == crate::effects::MemoryOrder::Relaxed {
                    format!("{operation}:i{width}")
                } else {
                    format!("{operation}:{}:i{width}", order.as_str())
                })
            }
            crate::effects::Loc::Reg(_) => lowering_load_signature(&effect.value.expr),
            _ => None,
        })
        .collect::<Vec<_>>();
    let effect_order = lowering_effect_order(document, lowering);
    format!(
        "{{\"name\": {}, \"source_sequence\": [{}], \"target\": {}, \"requires\": {}, \
         \"cost\": {{\"source_cycles\": {}, \"target_cycles\": {}, \"benefit\": {}}}, \
         \"preserved_state\": {}, \"memory_effects\": {}, \"effect_order\": {}, \
         \"semantic_equivalence\": \"proven\"}}",
        json_string(&lowering.name),
        sources,
        lowering_step_json(document, &lowering.target),
        requires,
        lowering.source_cycles,
        lowering.target_cycles,
        lowering.benefit,
        json_list(&preserved_state),
        json_list(&memory_effects),
        json_list(&effect_order)
    )
}

fn lowering_effect_order(document: &Document, lowering: &Lowering) -> Vec<String> {
    let mut order = Vec::new();
    for step in &lowering.sources {
        let Some(instruction) = document.instructions.iter().find(|instruction| {
            instruction.mnemonic.eq_ignore_ascii_case(&step.instruction)
                || instruction.name.eq_ignore_ascii_case(&step.instruction)
        }) else {
            continue;
        };
        if let Some(behavior) = &instruction.behavior {
            for effect in &behavior.effects {
                let entry = match &effect.loc {
                    crate::effects::Loc::Reg(name) => match lowering_binding_value(step, name) {
                        Some(LoweringValue::Variable(variable)) => {
                            if let Some(load) = lowering_load_signature(&effect.value.expr) {
                                format!("register:${variable}<-{load}")
                            } else {
                                format!("register:${variable}")
                            }
                        }
                        Some(LoweringValue::Literal(value)) => {
                            format!("discard:{name}={value}")
                        }
                        None => continue,
                    },
                    crate::effects::Loc::State { name, width } => {
                        format!("state:{name}:i{width}")
                    }
                    crate::effects::Loc::Mem {
                        width,
                        order,
                        atomic,
                        ..
                    } => {
                        let operation = if *atomic { "atomic-store" } else { "store" };
                        if *order == crate::effects::MemoryOrder::Relaxed {
                            format!("{operation}:i{width}")
                        } else {
                            format!("{operation}:{}:i{width}", order.as_str())
                        }
                    }
                    crate::effects::Loc::FixedReg { kind, index, width } => {
                        format!("fixed-register:{kind}:{index}:i{width}")
                    }
                    crate::effects::Loc::Barrier { kind, width } => {
                        format!("barrier:{kind}:i{width}")
                    }
                    // A channel, and how wide the message is. A lowering that
                    // claims to implement a guest `send` has to say the same.
                    crate::effects::Loc::Port { width, .. } => format!("send:i{width}"),
                    crate::effects::Loc::Pc if effect.guard.is_some() => "pc:guarded".to_string(),
                    crate::effects::Loc::Pc => "pc".to_string(),
                    crate::effects::Loc::Trap => "trap".to_string(),
                };
                order.push(if effect.atomic_group == 0 {
                    entry
                } else {
                    format!("atomic-group:{}:{entry}", effect.atomic_group)
                });
            }
        } else {
            for output in instruction.operands.iter().filter(|operand| operand.output) {
                if let Some(LoweringValue::Variable(variable)) =
                    lowering_binding_value(step, &output.name)
                {
                    order.push(format!("register:${variable}"));
                }
            }
        }
    }
    order
}

fn lowering_binding_value<'a>(step: &'a LoweringStep, operand: &str) -> Option<&'a LoweringValue> {
    step.bindings
        .iter()
        .find(|binding| binding.operand == operand)
        .map(|binding| &binding.value)
}

fn lowering_load_signature(expression: &crate::semantics::SemanticExpr) -> Option<String> {
    let crate::semantics::SemanticExpr::List(items) = expression else {
        return None;
    };
    let [crate::semantics::SemanticExpr::Atom(operator), crate::semantics::SemanticExpr::Atom(width), crate::semantics::SemanticExpr::Atom(signedness), rest @ ..] =
        items.as_slice()
    else {
        return None;
    };
    if !matches!(operator.as_str(), "load" | "atomic_load") || !matches!(rest.len(), 1 | 2) {
        return None;
    }
    let operation = if operator == "atomic_load" {
        "atomic-load"
    } else {
        "load"
    };
    if rest.len() == 2 {
        let crate::semantics::SemanticExpr::Atom(order) = &rest[0] else {
            return None;
        };
        Some(format!("{operation}:{order}:{signedness}:{width}"))
    } else {
        Some(format!("{operation}:{signedness}:{width}"))
    }
}

fn lowering_step_json(document: &Document, step: &LoweringStep) -> String {
    let instruction = document
        .instructions
        .iter()
        .find(|instruction| {
            instruction.mnemonic.eq_ignore_ascii_case(&step.instruction)
                || instruction.name.eq_ignore_ascii_case(&step.instruction)
        })
        .expect("validated lowering instruction");
    let layout = layout_for(document, instruction);
    let bindings = step
        .bindings
        .iter()
        .map(|binding| {
            let operand = instruction
                .operands
                .iter()
                .find(|operand| operand.name == binding.operand)
                .expect("validated lowering operand");
            let role = crate::ast::operand_role(operand, false);
            let value = match &binding.value {
                LoweringValue::Variable(variable) => format!(
                    "{{\"kind\": \"variable\", \"name\": {}}}",
                    json_string(variable)
                ),
                LoweringValue::Literal(value) => {
                    format!("{{\"kind\": \"literal\", \"value\": {value}}}")
                }
            };
            let fields = layout
                .operand_bindings(&binding.operand)
                .iter()
                .map(|field| {
                    format!(
                        "{{\"insn_lo\": {}, \"op_lo\": {}, \"width\": {}}}",
                        field.insn_lo, field.op_lo, field.width
                    )
                })
                .collect::<Vec<_>>()
                .join(", ");
            format!(
                "{{\"operand\": {}, \"role\": {role:?}, \"class\": {}, \"operand_kind\": {}, \"width\": {}, \
                 \"fields\": [{fields}], \"value\": {value}}}",
                json_string(&binding.operand),
                json_string(translation_operand_class(&operand.kind)),
                json_string(&operand.kind),
                operand.width
            )
        })
        .collect::<Vec<_>>()
        .join(", ");
    let constraint = instruction
        .decode_constraint
        .as_ref()
        .map(translation_constraint_json)
        .unwrap_or_else(|| "null".to_string());
    format!(
        "{{\"isa\": {}, \"mnemonic\": {}, \"match\": {}, \"mask\": {}, \
         \"decode_constraint\": {constraint}, \"bindings\": [{}]}}",
        json_string(&instruction.isa),
        json_string(&instruction.mnemonic),
        json_hex_u32(layout.match_value),
        json_hex_u32(layout.mask_value),
        bindings
    )
}

fn translation_constraint_json(constraint: &crate::decode_constraint::DecodeConstraint) -> String {
    use crate::decode_constraint::{ConstraintValue, DecodeConstraint};
    match constraint {
        DecodeConstraint::A64LogicalImmediate { width, n, imms } => {
            let n = match n {
                ConstraintValue::Literal(value) => {
                    format!("{{\"kind\": \"literal\", \"value\": {value}}}")
                }
                ConstraintValue::Operand(name) => {
                    format!("{{\"kind\": \"operand\", \"name\": {}}}", json_string(name))
                }
            };
            format!(
                "{{\"kind\": \"a64_logical_imm\", \"width\": {width}, \"n\": {n}, \"imms\": {}}}",
                json_string(imms)
            )
        }
        DecodeConstraint::A64ShiftedRegister {
            width,
            shift,
            amount,
        } => format!(
            "{{\"kind\": \"a64_shifted_reg\", \"width\": {width}, \"shift\": {}, \"amount\": {}}}",
            json_string(shift),
            json_string(amount)
        ),
        DecodeConstraint::A64ExtendedRegister { amount } => format!(
            "{{\"kind\": \"a64_extended_reg\", \"amount\": {}}}",
            json_string(amount)
        ),
        DecodeConstraint::UnsignedCompare {
            operand,
            op,
            literal,
        } => format!(
            "{{\"kind\": \"uimm_compare\", \"operand\": {}, \"op\": {}, \"literal\": {literal}}}",
            json_string(operand),
            json_string(op.name())
        ),
        DecodeConstraint::MaskedEq {
            operand,
            mask,
            value,
        } => format!(
            "{{\"kind\": \"uimm_mask_eq\", \"operand\": {}, \"mask\": {mask}, \"value\": {value}}}",
            json_string(operand)
        ),
        DecodeConstraint::And(children) | DecodeConstraint::Or(children) => {
            let kind = if matches!(constraint, DecodeConstraint::And(_)) {
                "and"
            } else {
                "or"
            };
            let children = children
                .iter()
                .map(translation_constraint_json)
                .collect::<Vec<_>>()
                .join(", ");
            format!("{{\"kind\": \"{kind}\", \"constraints\": [{children}]}}")
        }
        DecodeConstraint::Not(child) => format!(
            "{{\"kind\": \"not\", \"constraint\": {}}}",
            translation_constraint_json(child)
        ),
    }
}

fn lowering_predicate_json(predicate: &LoweringPredicate) -> String {
    match predicate {
        LoweringPredicate::Compare { lhs, op, rhs } => format!(
            "{{\"kind\": \"compare\", \"op\": {}, \"lhs\": {}, \"rhs\": {}}}",
            json_string(op.name()),
            lowering_value_json(lhs),
            lowering_value_json(rhs)
        ),
        LoweringPredicate::And(children) | LoweringPredicate::Or(children) => {
            let kind = if matches!(predicate, LoweringPredicate::And(_)) {
                "and"
            } else {
                "or"
            };
            let children = children
                .iter()
                .map(lowering_predicate_json)
                .collect::<Vec<_>>()
                .join(", ");
            format!("{{\"kind\": \"{kind}\", \"predicates\": [{children}]}}")
        }
        LoweringPredicate::Not(child) => format!(
            "{{\"kind\": \"not\", \"predicate\": {}}}",
            lowering_predicate_json(child)
        ),
    }
}

fn lowering_value_json(value: &LoweringValue) -> String {
    match value {
        LoweringValue::Variable(variable) => format!(
            "{{\"kind\": \"variable\", \"name\": {}}}",
            json_string(variable)
        ),
        LoweringValue::Literal(value) => {
            format!("{{\"kind\": \"literal\", \"value\": {value}}}")
        }
    }
}

fn instruction_role<'a>(document: &'a Document, instruction: &Instruction) -> Option<&'a str> {
    document
        .isas
        .iter()
        .find(|isa| isa.name == instruction.isa)
        .map(|isa| isa.role.as_str())
}

/// Return a key only when the instruction is fully encodable and has one
/// semantic result. Translation entries must be executable mappings, not
/// merely expressions that happen to look alike.
fn translation_key(document: &Document, instruction: &Instruction) -> Option<String> {
    let layout = resolve_layout(document, instruction).ok()?;
    if !layout.unencoded_operands.is_empty() || !layout.unbound_fields.is_empty() {
        return None;
    }
    let outputs: Vec<&Operand> = instruction
        .operands
        .iter()
        .filter(|operand| operand.output)
        .collect();
    if outputs.len() != 1 {
        return None;
    }
    let root_width = outputs[0].width;
    let inputs: Vec<&Operand> = instruction
        .operands
        .iter()
        .filter(|operand| operand.input)
        .collect();
    let symbols: HashMap<&str, usize> = inputs
        .iter()
        .enumerate()
        .map(|(idx, operand)| (operand.name.as_str(), idx))
        .collect();
    let input_types = inputs
        .iter()
        .map(|operand| {
            format!(
                "{}:{}",
                translation_operand_class(&operand.kind),
                operand.width
            )
        })
        .collect::<Vec<_>>()
        .join(",");
    let semantics = if instruction.formal_semantics.trim().is_empty() {
        canonical_register_effect(instruction, outputs[0], &symbols)?
    } else {
        let expr = parse_formal_semantics(&instruction.formal_semantics).ok()?;
        let sem = lower(&expr, root_width).ok()?;
        canonical_sem(&sem, &symbols)?
    };
    Some(format!(
        "out={}:{};in=[{}];sem={}",
        translation_operand_class(&outputs[0].kind),
        outputs[0].width,
        input_types,
        semantics
    ))
}

/// Effect-only A64 helpers are still pure value computations when the behavior
/// is exactly one unconditional write to the declared output. Preserve those
/// helpers as canonical expression nodes so custom targets can match them
/// without pretending they belong to the smaller generic formal-semantics IR.
fn canonical_register_effect(
    instruction: &Instruction,
    output: &Operand,
    symbols: &HashMap<&str, usize>,
) -> Option<String> {
    let behavior = instruction.behavior.as_ref()?;
    let [effect] = behavior.effects.as_slice() else {
        return None;
    };
    if effect.guard.is_some() {
        return None;
    }
    match &effect.loc {
        crate::effects::Loc::Reg(name) if name == &output.name => {}
        _ => return None,
    }
    canonical_effect_expr(&effect.value.expr, symbols)
}

fn canonical_effect_expr(expr: &SemanticExpr, symbols: &HashMap<&str, usize>) -> Option<String> {
    match expr {
        SemanticExpr::Atom(atom) => Some(
            symbols
                .get(atom.as_str())
                .map_or_else(|| atom.clone(), |index| format!("${index}")),
        ),
        SemanticExpr::List(items) => {
            let (head, args) = items.split_first()?;
            let SemanticExpr::Atom(op) = head else {
                return None;
            };
            let args = args
                .iter()
                .map(|arg| canonical_effect_expr(arg, symbols))
                .collect::<Option<Vec<_>>>()?;
            Some(format!("{op}({})", args.join(",")))
        }
    }
}

/// Where an operand's register file starts in the flat register array. The
/// executors key registers by `offset + index`, and a consumer that assumed
/// index alone was reading the general-purpose file no matter which file the
/// operand named -- correct for every class at offset zero, and silently wrong
/// for the first one above it.
fn translation_slot_offset(kind: &str) -> u32 {
    crate::ast::register_class(kind).map_or(0, |class| class.offset)
}

/// How many slots one register of a class occupies, published beside the
/// offset because a consumer needs both to reach a register.
///
/// `offset + index` was the whole answer while every register was one slot.
/// AArch64's `V` is 128 bits and held as two limbs, so `d1` is at slot 34 and
/// not 33, and a consumer doing the old arithmetic read the register before it.
fn translation_slot_stride(kind: &str) -> u32 {
    crate::ast::register_class(kind).map_or(1, |class| class.limbs.max(1))
}

/// Architectural register classes may have special state behavior while still
/// being value-compatible with a target core's ordinary register operand --
/// which is what the lowering family says, so it is what this reports. Every
/// general-purpose class names the family `reg` and so is unchanged; a class in
/// a *different file* names a different one, and that is the distinction this
/// used to lose.
///
/// It lost it silently until a corpus held two instructions differing only by
/// which file their operands live in: AArch64's two `FMOV` forms both move
/// sixty-four bits and are told apart by nothing else, so they keyed alike and
/// the translation map paired each with the other's target.
fn translation_operand_class(kind: &str) -> &str {
    match crate::ast::register_class(kind) {
        Some(class) => class.lowering_family,
        None => kind,
    }
}

fn canonical_sem(sem: &Sem, symbols: &HashMap<&str, usize>) -> Option<String> {
    Some(match sem {
        Sem::Sym(name) => format!("${}", symbols.get(name.as_str())?),
        Sem::Int { value, width } => format!("i{width}:{value}"),
        Sem::App { op, width, args } => {
            let args = args
                .iter()
                .map(|arg| canonical_sem(arg, symbols))
                .collect::<Option<Vec<_>>>()?;
            format!("{}<i{}>({})", op_name(*op), width, args.join(","))
        }
        Sem::Ext {
            op,
            width,
            from_bits,
            arg,
        } => format!(
            "{}<i{},{}>({})",
            op_name(*op),
            width,
            from_bits,
            canonical_sem(arg, symbols)?
        ),
        // By name: two instructions calling the same function on the same
        // arguments compute the same thing.
        Sem::Call { name, width, args } => {
            let args = args
                .iter()
                .map(|(param, arg)| Some(format!("i{param}:{}", canonical_sem(arg, symbols)?)))
                .collect::<Option<Vec<_>>>()?;
            format!("call<{name},i{width}>({})", args.join(","))
        }
    })
}

fn op_name(op: Op) -> &'static str {
    match op {
        // The dialect has no rounding-mode form; `canonical_sem` refuses these
        // expressions before this is reached, so the name is only ever a label.
        Op::FaddFx => "fadd_fx",
        Op::FsubFx => "fsub_fx",
        Op::FmulFx => "fmul_fx",
        Op::FdivFx => "fdiv_fx",
        Op::FsqrtFx => "fsqrt_fx",
        Op::FmaFx => "fma_fx",
        Op::FaddRm => "fadd_rm",
        Op::FsubRm => "fsub_rm",
        Op::FmulRm => "fmul_rm",
        Op::FdivRm => "fdiv_rm",
        Op::FsqrtRm => "fsqrt_rm",
        Op::FmaRm => "fma_rm",
        Op::Fneg => "fneg",
        Op::Mulh => "mulh",
        Op::Mulhu => "mulhu",
        Op::Mulhsu => "mulhsu",
        Op::IcmpEq => "icmp_eq",
        Op::IcmpNe => "icmp_ne",
        Op::IcmpSlt => "icmp_slt",
        Op::IcmpSge => "icmp_sge",
        Op::IcmpUlt => "icmp_ult",
        Op::IcmpUge => "icmp_uge",
        Op::Fsqrt => "fsqrt",
        Op::FcvtF2S => "fcvt_f2s",
        Op::FcvtF2U => "fcvt_f2u",
        Op::FcvtS2F => "fcvt_s2f",
        Op::FcvtU2F => "fcvt_u2f",
        Op::FcvtF2F => "fcvt_f2f",
        Op::Ones => "ones",
        Op::Zeros => "zeros",
        Op::FcvtF2SFx => "fcvt_f2s_fx",
        Op::FcvtF2UFx => "fcvt_f2u_fx",
        Op::FcvtS2FFx => "fcvt_s2f_fx",
        Op::FcvtU2FFx => "fcvt_u2f_fx",
        Op::FcvtF2FFx => "fcvt_f2f_fx",
        Op::FcmpOeq => "fcmp_oeq",
        Op::FcmpOlt => "fcmp_olt",
        Op::FcmpOle => "fcmp_ole",
        Op::FcmpUno => "fcmp_uno",
        Op::Fma => "fma",
        Op::Fadd => "fadd",
        Op::Fsub => "fsub",
        Op::Fmul => "fmul",
        Op::Fdiv => "fdiv",
        Op::Add => "add",
        Op::Sub => "sub",
        Op::Mul => "mul",
        Op::Udiv => "udiv",
        Op::Sdiv => "sdiv",
        Op::Urem => "urem",
        Op::Srem => "srem",
        Op::And => "and",
        Op::Or => "or",
        Op::Xor => "xor",
        Op::Shl => "shl",
        Op::Lshr => "lshr",
        Op::Ashr => "ashr",
        Op::Rol => "rol",
        Op::Ror => "ror",
        Op::Not => "not",
        Op::Clz => "clz",
        Op::Ctz => "ctz",
        Op::Cpop => "cpop",
        Op::MinS => "mins",
        Op::MaxS => "maxs",
        Op::MinU => "minu",
        Op::MaxU => "maxu",
        Op::Select => "select",
        Op::Sext => "sext",
        Op::Zext => "zext",
    }
}

fn translation_match_json(
    document: &Document,
    source: &Instruction,
    target: &Instruction,
    semantic_key: &str,
) -> String {
    let source_layout = layout_for(document, source);
    let target_layout = layout_for(document, target);
    let source_inputs: Vec<&Operand> = source
        .operands
        .iter()
        .filter(|operand| operand.input)
        .collect();
    let target_inputs: Vec<&Operand> = target
        .operands
        .iter()
        .filter(|operand| operand.input)
        .collect();
    let source_output = source.operands.iter().find(|operand| operand.output);
    let target_output = target.operands.iter().find(|operand| operand.output);
    let mut mappings = Vec::new();
    if let (Some(source_output), Some(target_output)) = (source_output, target_output) {
        mappings.push(format!(
            "{{\"source\": {}, \"target\": {}, \"role\": \"out\", \"class\": {}, \
             \"register\": {}, \"slot_offset\": {}, \"slot_stride\": {}, \"width\": {}}}",
            json_string(&source_output.name),
            json_string(&target_output.name),
            json_string(translation_operand_class(&source_output.kind)),
            crate::ast::is_register_kind(&source_output.kind),
            translation_slot_offset(&source_output.kind),
            translation_slot_stride(&source_output.kind),
            source_output.width
        ));
    }
    for (source_input, target_input) in source_inputs.iter().zip(target_inputs.iter()) {
        mappings.push(format!(
            "{{\"source\": {}, \"target\": {}, \"role\": \"in\", \"class\": {}, \
             \"register\": {}, \"slot_offset\": {}, \"slot_stride\": {}, \"width\": {}}}",
            json_string(&source_input.name),
            json_string(&target_input.name),
            json_string(translation_operand_class(&source_input.kind)),
            crate::ast::is_register_kind(&source_input.kind),
            translation_slot_offset(&source_input.kind),
            translation_slot_stride(&source_input.kind),
            source_input.width
        ));
    }
    format!(
        "{{\"source_isa\": {}, \"source_mnemonic\": {}, \"source_match\": {}, \"source_mask\": {}, \
         \"target_isa\": {}, \"target_mnemonic\": {}, \"target_base\": {}, \"target_mask\": {}, \
         \"operand_map\": [{}], \"semantic_key\": {}}}",
        json_string(&source.isa),
        json_string(&source.mnemonic),
        json_hex_u32(source_layout.match_value),
        json_hex_u32(source_layout.mask_value),
        json_string(&target.isa),
        json_string(&target.mnemonic),
        json_hex_u32(target_layout.match_value),
        json_hex_u32(target_layout.mask_value),
        mappings.join(", "),
        json_string(semantic_key)
    )
}
